let reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const control=document.querySelector('#reduce');control.setAttribute('aria-pressed',reduced);control.onclick=()=>{reduced=!reduced;control.setAttribute('aria-pressed',reduced);};
barba.init({preventRunning:true,transitions:[{name:'atlas-shutter',async leave(){if(reduced)return;document.querySelector('.shutter').style.pointerEvents='all';await gsap.to('.shutter i',{scaleY:1,duration:.35,stagger:.04,ease:'power3.inOut'});},async enter(data){document.title=new DOMParser().parseFromString(data.next.html,'text/html').title;window.scrollTo(0,0);if(!reduced){gsap.set('.shutter i',{transformOrigin:'top'});await gsap.to('.shutter i',{scaleY:0,duration:.45,stagger:.035,ease:'power3.inOut'});gsap.set('.shutter i',{transformOrigin:'bottom'});}document.querySelector('.shutter').style.pointerEvents='none';data.next.container.focus({preventScroll:true});}}]});
matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change',e=>{reduced=e.matches;control.setAttribute('aria-pressed',reduced);});
